void Menu_Shop::GainFocus()
{
	IMenu::GainFocus();

	SelectWeapon(m_selected);
	m_TE_weapons->SetEnabled( true );
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------

void Menu_Shop::LoseFocus()
{
	IMenu::LoseFocus();
	m_TE_weapons->SetEnabled( false );
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
void Menu_Shop::ChangeCurrentMenu(IMenu* menu, bool gain_focus)
{
	if( m_pCurrentSubMenu == menu )
		return;

	if( m_pCurrentSubMenu != NULL ) 
		m_pCurrentSubMenu->SubMenus_LoseFocus();

	m_pCurrentSubMenu = menu;

	if( gain_focus )
		m_pCurrentSubMenu->GainFocus();
}


//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
void Menu_Shop::Draw()
{
	if (!m_isInitialized) return;

	// Draw 3D Weapons
	{
		// Start
		__IRR_DRIVER()->endScene2D();

		// Draw Transperant floor -> update ZBuffer
		m_floor->setVisible(true);

		for (int i = 0; i < m_weaponCount; i++)
		{
			m_weapons[i]->setVisible(false);
		}

		__IRR_SCENE()->drawAll();

		// Draw 2D Background
		__IRR_DRIVER()->beginScene2D();
		m_shopSprite->PaintFrame(MENU_F_SHOP_BG_SHOP, 0, 0, 255);
		__IRR_DRIVER()->endScene2D();

		// Draw 3D Weapons
		m_floor->setVisible(false);

		for (int i = 0; i < m_weaponCount; i++)
		{
			m_weapons[i]->setVisible(true);
		}

		__IRR_SCENE()->drawAll();

		// Done
		__IRR_DRIVER()->beginScene2D();
	}

	/* Debug * /
	p2i pos = screenFrom3DPos(k_weapon_pos_center);
	__IRR_DRIVER()->draw2DLine( p2i(0, pos.Y), p2i(480, pos.Y) );
	__IRR_DRIVER()->draw2DLine( p2i(pos.X, 0), p2i(pos.X, 320) );
	/**/
	// Selected Weapon/Upgrade Desc
	DrawWeaponDescription();

	// Draw Title
	DrawTitle();

	// Available Money
	DrawAvailableMoney();

	/* Debug weapon scroll area and arrows * /
	__IRR_DRIVER()->draw2DRectangle(SColor(128,255,0,0), r2i(p2i(k_arrow_lx - k_arrow_w/2, k_arrow_y - k_arrow_h/2), d2i(k_arrow_w, k_arrow_h)));
	__IRR_DRIVER()->draw2DRectangle(SColor(128,255,0,0), r2i(p2i(k_arrow_rx - k_arrow_w/2, k_arrow_y - k_arrow_h/2), d2i(k_arrow_w, k_arrow_h)));
	__IRR_DRIVER()->draw2DRectangle(SColor(128,0,255,0), r2i(p2i(k_scroll_x, k_scroll_y), d2i(k_scroll_w, k_scroll_h)));
	/**/

	IMenu::Draw();
}


//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
void Menu_Shop::Update( float dt )
{
	if (!m_isInitialized) 
		return;

	IMenu::Update( dt );

	f32 dt_sec = dt/1000;

	UpdateScrollInput(dt_sec);
	UpdateSliderInput(dt_sec);
	UpdateHighlight(dt_sec);

	for (int i = 0; i < m_weaponCount; i++)
	{
		m_weapons[i]->update(dt_sec);
	}

	// Update current menu
	//-------------------------------
	//m_pCurrentSubMenu->Update();

	UpdateMenuMusic();

	if (Transition_IsGoing())
		return;

	if( m_menuConfirmation->IsOnFocus() && m_menuConfirmation->GetDialogResult() != RESULT_NONE)
	{
		SubMenu_Remove();

		if(m_menuConfirmation->GetDialogResult() == RESULT_YES)
		{
			m_exit = true;

			/// Cheack achievement "Lock & Load"
			CLevelStats & stats = CPlayfield::GetInstance()->GetLevelStats();

			s32 i = 0;
			while( i < WT_Count - 1 && stats.WeaponLevel[i] == (WL_Count-1) ) i++;

			if( i == WT_Count - 1 )
				__ACHIEVEMENTS()->setAchieved( "Lock & Load" ); 
		}
		GainFocus();
	}

	if (m_exit)
	{
		__MGR_STATES()->switchState<GSLevel>();
	}

	/// Add achievement 'Addicted'
	__ACHIEVEMENTS()->addValue( "Addicted", (u32)dt );
}

