//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------

void Menu_Shop::DrawWeaponDescription()
{
	CLevelStats & stats = CPlayfield::GetInstance()->GetLevelStats();
	EWeaponType weapon = m_weapons[m_selected]->getType();
	const SUpgradeInfo & info = GetWeaponInfo(weapon, m_level);

	bool spell = (weapon == WT_Spell);
	int gold = info.getPriceGold();
	int souls = info.getPriceSouls();
	wchar_t txt[32];

	// Box
	m_shopSprite->PaintFrame(MENU_F_SHOP_WINDOW, k_desc_box_x, k_desc_box_y, 255);

	// Title
	const wchar_t * title = _TXT_INT(info.Name);
	float oldScaleX = __FONT("MS_Title")->GetScaleX();
	float oldScaleY = __FONT("MS_Title")->GetScaleY();
	__FONT("MS_Title")->SetScale( 0.8 );
	__FONT("MS_Title")->DrawString(title, k_desc_title_x, k_desc_title_y, CFont::HVCENTER);
	__FONT("MS_Title")->SetScale( oldScaleX, oldScaleY );

	// Description
	const wchar_t * desc = _TXT_INT(info.Description);
	__FONT("MS_Text")->DrawWrappedText(desc, k_desc_text_x, k_desc_text_y, k_desc_text_w, CFont::HVCENTER);

	// Level
	if (!spell)
	{
		stringw str = FormatString(L"%s %d", _TXT(MENU_LEVEL), (int)m_level + 1);
		__FONT("MS_SmallNormal")->DrawString(str.c_str(), k_desc_level_x, k_desc_level_y, CFont::VCENTER);
	}

	// Price : gold
	if (IsWeaponBought(m_selected, m_level))
	{
		const wchar_t * text =  _TXT(MENU_SOLD);
		__FONT("MS_SmallNormal")->DrawString(text, k_desc_gold_value_x, k_desc_gold_value_y, CFont::VCENTER | CFont::HCENTER );
	}
	else
	{
		CFont * font;
		m_shopSprite->PaintFrame(MENU_F_SHOP_GOLD, k_desc_gold_icon_x, k_desc_gold_icon_y);
		font = (gold <= stats.Gold) ? __FONT("MS_SmallNormal") : __FONT("MS_SmallRed");
		font->DrawString(FormatNumber(gold).c_str(), k_desc_gold_value_x, k_desc_gold_value_y, CFont::VCENTER);

		m_shopSprite->PaintFrame(MENU_F_SHOP_SOULS, k_desc_souls_icon_x, k_desc_souls_icon_y);
		font = (souls <= stats.Souls) ? __FONT("MS_SmallNormal") : __FONT("MS_SmallRed");
		font->DrawString(FormatNumber(souls).c_str(), k_desc_souls_value_x, k_desc_souls_value_y, CFont::VCENTER);
	}
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------

void Menu_Shop::DrawAvailableMoney()
{
	CLevelStats & stats = CPlayfield::GetInstance()->GetLevelStats();
	int souls = stats.Souls;
	int gold = stats.Gold;

	CFont* font = __FONT("MS_SmallGold");
	wchar_t txt[32];

	// Souls Box
	m_shopSprite->PaintFrame(MENU_F_SHOP_MONEY_SOUL_BAR, k_soul_box_x, k_soul_box_y);

	// Souls
	m_shopSprite->PaintFrame(MENU_F_SHOP_SOULS, k_soul_icon_x, k_soul_box_y);
	font->DrawString(FormatNumber(souls).c_str(), k_soul_value_x, k_soul_box_y, CFont::VCENTER | CFont::RIGHT);

	// Gold Box
	m_shopSprite->PaintFrame(MENU_F_SHOP_MONEY_SOUL_BAR, k_money_box_x, k_money_box_y);

	// Gold
	m_shopSprite->PaintFrame(MENU_F_SHOP_GOLD, k_money_icon_x, k_money_box_y);
	font->DrawString(FormatNumber(gold).c_str(), k_money_value_x, k_money_box_y, CFont::VCENTER | CFont::RIGHT);
}

//---------------------------------------------------------------------------------------------------------
// Perform Visual control actions
//---------------------------------------------------------------------------------------------------------
void Menu_Shop::VisualControlDoAction( IVisualControl* visual_control, int action_id )
{
	switch (action_id)
	{
	case button_action_lose_focus:
		{
			if (visual_control->GetActionId() == action_left ||
				visual_control->GetActionId() == action_right )
			{
				visual_control->GetTouchElement()->ReassignTouchTo(m_TE_weapons);
			}
			break;
		}
		break;

	case action_left:
		{
			NextWeapon();
		}
		break;

	case action_right:
		{
			PrevWeapon();
		}
		break;

	case action_buy:
		{
			BuyWeapon(m_selected, m_level);
			SelectWeapon(m_selected);			
		}
		break;

	case action_exit:
		{
			m_menuConfirmation->SetConfirmationText( _TXT_ID(MENU_EXIT_SHOP_CONFIRMATION) );
			LoseFocus();
			SubMenu_Change( "Menu_Confirmation" );
		}
		break;

	default:
		{
		}
		break;
	}
}

