void Menu_Shop::SelectWeapon(int item)
{
	m_selected = item;
	EWeaponType weapon = m_weapons[item]->getType();

	SelectLevel( m_weapons[item]->getLevel() );

	if (weapon == WT_Spell)
	{
		m_slider_level->SetVisible(false);
		m_slider_level->SetEnabled(false);
	}
	else
	{
		CLevelStats & stats = CPlayfield::GetInstance()->GetLevelStats();
		int level = stats.WeaponLevel[weapon];

		int frame = MENU_F_SHOP_SLIDER_BG_00 + level + 1;
		m_slider_level->ChangeFrame(slider_frame_empty, frame);
		m_slider_level->SetVisible(true);
		m_slider_level->SetEnabled(true);
	}
}

void Menu_Shop::SelectLevel(int level)
{
	m_level = level;

	m_weapons[m_selected]->setLevel(m_level);

	int frame = MENU_F_SHOP_SLIDER_BTN_NORMAL;
	int frame_glow = MENU_F_SHOP_SLIDER_BTN_GLOW;

	if (IsWeaponBought(m_selected, m_level))
	{
		m_btn_buy->SetEnabled(false);
	}
	else
	{
		if (CanBuyWeapon(m_selected, m_level))
		{
			m_btn_buy->SetEnabled(true);
			m_btn_buy->SetSelected(false);
		}
		else
		{
			m_btn_buy->SetEnabled(false);
			frame = MENU_F_SHOP_SLIDER_BTN_DISABLED;
			frame_glow = MENU_F_SHOP_SLIDER_BTN_DISABLED;
		}
	}

	m_slider_level->ChangeFrame(slider_frame_btn, frame);
	m_slider_level->ChangeFrame(slider_frame_btn_glow, frame_glow);
}

