void Menu_Shop::NextWeapon()
{
	AdjustTargetAngle( +2.0f * Float::PI / m_weaponCount );

	__MGR_SOUNDS()->play( SFX_MENU_SLIDER_MOVE );
}

void Menu_Shop::PrevWeapon()
{
	AdjustTargetAngle( -2.0f * Float::PI / m_weaponCount );

	__MGR_SOUNDS()->play( SFX_MENU_SLIDER_MOVE );
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------

void Menu_Shop::RotateWeapons(f32 angle)
{
	for (int i = 0; i < m_weaponCount; i++)
	{
		f32 rot = (angle - WeaponToAngle(i));
		f32 scale_ratio = (cosf(rot) + 1) / 2.0f;
		rot += k_weapon_pos_angle;

		v3f pos = v3f(0, 0, k_weapon_pos_radius);
		pos.rotateXZBy(rot * 360.0f / (2.0f * Float::PI));
		pos += k_weapon_pos_center;

		v3f rotation = v3f(0, k_weapon_rot, 0);

		const f32 scale_min = 0.8f;
		const f32 scale_max = 1.0f;
		f32 scale = (scale_min + (scale_max - scale_min) * scale_ratio);
		scale *= k_weapon_scale;

		CWeaponObject * weapon = m_weapons[i];
		switch (weapon->getType())
		{
		case WT_Gate:
			weapon->setPosition(pos);
			weapon->setScale(scale);
			weapon->getSceneNode()->setRotation(-rotation + v3f(0, PI, 0));
			break;

		case WT_Hydra:
			m_hydraPool->setPosition(pos+v3f(0,0,0));
			m_hydraPool->setScale(v3f(1,1,1)*scale);
			m_hydraPool->setRotation(v3f(0, PI, 0));

			pos += v3f(0, -25, 0);
			weapon->setPosition(pos);
			weapon->setScale(scale);
			weapon->getSceneNode()->setRotation(rotation + v3f(0,PI,0));
			break;

		case WT_Fireball:
			{
				CFireball* fireball = (CFireball*)weapon;

				v3f offset = v3f(0, 63, 0);
				fireball->setPosition(pos + offset);
				fireball->setScale(scale);
				fireball->getSceneNode()->setRotation(rotation);

				fireball->getPostament()->setPosition(pos);
				fireball->getPostament()->setScale(v3f(1,1,1)*scale);
				fireball->getPostament()->setRotation(rotation + v3f(0, PI, 0));
			}
			break;

		case WT_Iceball:
			{
				CIceball* iceball = (CIceball*)weapon;

				v3f offset = v3f(0, 67, 0);
				iceball->setPosition(pos + offset);
				iceball->setScale(scale);
				iceball->getSceneNode()->setRotation(rotation);

				iceball->getPostament()->setPosition(pos);
				iceball->getPostament()->setScale(v3f(1,1,1)*scale);
				iceball->getPostament()->setRotation(rotation + v3f(0, PI, 0));
			}
			break;

		case WT_Griffin:
			weapon->setPosition(pos);
			weapon->setScale(scale);
			weapon->getSceneNode()->setRotation(rotation);
			break;

		case WT_Spell:
			weapon->getSceneNode()->setPosition(pos + v3f(0, 60, 0));
			weapon->getSceneNode()->setScale(v3f(1,1,1)*scale*1.6f);
			weapon->getSceneNode()->setRotation(rotation + v3f(0, PI, 0));
			break;
		}
	}
}

