//---------------------------------------------------------------------------------------------------------

bool Menu_Shop::IsWeaponBought(int item, int level)
{
	EWeaponType weapon = m_weapons[item]->getType();
	CLevelStats & stats = CPlayfield::GetInstance()->GetLevelStats();

	if (CGameConfig::AllowDowngrades)
	{
		return level == stats.WeaponLevel[weapon];
	}

	if (weapon == WT_Spell)
	{
		return stats.WeaponLevel[weapon] == stats.SpellAvailable;
	}
	else
	{
		return stats.WeaponLevel[weapon] >= level;
	}
}

bool Menu_Shop::CanBuyWeapon(int item, int level)
{
	EWeaponType weapon = m_weapons[item]->getType();
	CLevelStats & stats = CPlayfield::GetInstance()->GetLevelStats();
	const SUpgradeInfo & info = GetWeaponInfo(weapon, level);

	bool enoughGold = stats.Gold >= info.getPriceGold();
	bool enoughSouls = stats.Souls >= info.getPriceSouls();

	return enoughGold && enoughSouls;
}

void Menu_Shop::BuyWeapon(int item, int level)
{
	EWeaponType weapon = m_weapons[item]->getType();
	CLevelStats & stats = CPlayfield::GetInstance()->GetLevelStats();
	const SUpgradeInfo & info = GetWeaponInfo(weapon, level);

	int oldLevel = stats.WeaponLevel[weapon];

	/// Check achievement 'Picky Customer'
	if (weapon != WT_Spell && level >= stats.WeaponLevel[weapon] + 2)
	{
		__ACHIEVEMENTS()->setAchieved( "Picky Customer" );
	}

	stats.WeaponLevel[weapon] = level;

	stats.Gold -= info.getPriceGold();
	stats.Souls -= info.getPriceSouls();

	if (oldLevel == WL_None && weapon == WT_Griffin)
	{
		m_nextCutscene = stats.WeaponLevel[WT_Hydra] == WL_None ? CPlayfield::CS_Griffin : CPlayfield::CS_HydraGriffin;
	}
	else if (weapon == WT_Hydra && level == WL_1)
	{
		m_nextCutscene = stats.WeaponLevel[WT_Griffin] == WL_None ? CPlayfield::CS_Hydra : CPlayfield::CS_HydraGriffin;
	}
	else if (weapon == WT_Hydra && level == WL_3)
	{
		m_nextCutscene = CPlayfield::CS_Hydra3Heads;
	}
}

