//---------------------------------------------------------------------------------------------------------

int Menu_Shop::AngleToWeapon(f32 angle)
{
	const f32 snap_angle = 2.0f * Float::PI / m_weaponCount;
	angle += snap_angle/2;

	while (angle < 0.0f) 
		angle += 2.0f * Float::PI;

	while (angle >= 2.0f * Float::PI) 
		angle -= 2.0f * Float::PI;

	int weapon = (int)(angle / snap_angle);
	CLAMP(weapon, 0, m_weaponCount);
	return weapon;
}

f32 Menu_Shop::WeaponToAngle(int weapon)
{
	return 2.0f * Float::PI * weapon / m_weaponCount;
}

void Menu_Shop::AdjustTargetAngle(f32 offset)
{
	m_angle_target += offset;

	// Correct target angle to [0, 2*PI) range
	while (m_angle_target >= 2 * Float::PI)
	{
		m_angle_target -= Float::PI * 2;
		m_angle_current -= Float::PI * 2;
	}
	while (m_angle_target < 0)
	{
		m_angle_target += Float::PI * 2;
		m_angle_current += Float::PI * 2;
	}
}

void Menu_Shop::SetStartingWeapon()
{
	int selected = 0;
	for (int i = 0; i < m_weaponCount; i++)
	{
		EWeaponType type = m_weapons[i]->getType();
		int level = m_weapons[i]->getLevel();
		if (type == WT_Spell)
		{
			if (!IsWeaponBought(i, level) && CanBuyWeapon(i, level))
			{
				selected = i;
				break;
			}
		}
		else
		{
			if (!IsWeaponBought(i, level) && CanBuyWeapon(i, level))
			{
				selected = i;
				break;
			}
			int levelNext = CLAMPED(level + 1, WL_First, WL_Last);
			if (!IsWeaponBought(i, levelNext) && CanBuyWeapon(i, levelNext))
			{
				m_weapons[i]->setLevel(levelNext);
				selected = i;
				break;
			}
		}

	}
	AdjustTargetAngle( WeaponToAngle(selected) );
	m_angle_current = m_angle_target;
	SelectWeapon(selected);
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------

void Menu_Shop::UpdateScrollInput(f32 time)
{
	/// Touch Activate/Release
	if (m_TE_weapons->IsNowActivated() )
	{
		m_TE_weapons->DisableAllOtherElements(true);
	}

	if ( m_TE_weapons->IsNowReleased() )
	{
		m_TE_weapons->DisableAllOtherElements(false);
		m_TE_weapons->ResetInput();
	}
	
	/// Touch Active -> Rotate Weapons
	if ( m_TE_weapons->IsActive() )
	{
		//TODO: Rotate weapons
		int dx, dy;
		m_TE_weapons->GetTouchPos_DT(dx, dy);
		f32 rotate = 2.0f * Float::PI * -dx / 360;

		if (!m_angle_skip)
		{
			f32 speed = fabs(rotate / time);
			f32 speed_threshold = 2.0f * Float::PI * 1.5f;

			if (speed >= speed_threshold)
			{
				m_angle_skip = true;
				if (rotate > 0)
					NextWeapon();
				else
					PrevWeapon();
			}
			else
			{
				AdjustTargetAngle(rotate);
			}
		}
	}
	else
	{
		m_angle_skip = false;
	}

	/// Snap target angle to item
	if (!m_TE_weapons->IsActive())
	{
		f32 snap_angle = 2.0f * Float::PI / m_weaponCount;
		f32 k = m_angle_target / snap_angle;
		while (k >= 1.0f)
			k -= 1.0f;

		if (k >= 0.5f)
			m_angle_target += (1.0f - k) * snap_angle;
		else
			m_angle_target -= (k) * snap_angle;
	}

	/// Current -> Target
	if (m_angle_current != m_angle_target)
	{
		f32 dist = m_angle_target - m_angle_current;
		f32 rotate = dist / 0.15f;

		if (fabs(dist) < Float::PI / 16)
			m_angle_skip = false;
		
		if (fabs(rotate) < Float::PI / 512.0)
		{
			m_angle_current = m_angle_target;
		}
		else
		{
			m_angle_current += rotate * time;
		}
	}
	else
	{
		m_angle_skip = false;
	}

	/// Rotate Models
	RotateWeapons(m_angle_current);

	// Select Current Weapon
	int item = AngleToWeapon(m_angle_current);
	if (item != m_selected)
		SelectWeapon(item);

}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------

void Menu_Shop::UpdateSliderInput(f32 time)
{
	VisualControlSlider * slider = m_slider_level;

	if (slider->GetSelected())
	{
		// update weapon level
		int val = slider->GetPercent();
		int level = IntRemap1(val, 0, 100, 0, 2);
		if (level != m_level)
		{
			SelectLevel(level);

			__MGR_SOUNDS()->play( SFX_MENU_SLIDER_MOVE );
		}
	}
	else
	{
		// snap slider to grid;
		int current = slider->GetPercent();
		int target = IntRemap1(m_level, 0, 3-1, 0, 100);
	
		if (current < target)
			slider->SetPercent( current + MAX(1, (target - current) / 4) );
		else if (current > target)
			slider->SetPercent( current - MAX(1, (current - target) / 4) );
	}
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------

void Menu_Shop::UpdateHighlight(f32 time)
{
	for (int i = 0; i < m_weaponCount; i++)
	{
		const f32 speed = 1.0f / 0.3f;
		m_highlight[i] += (i == m_selected ? speed : -speed) * time;
		CLAMP(m_highlight[i], 0.0f, 1.0f);

		m_weapons[i]->setShopHighlight(m_highlight[i]);

		if (m_weapons[i]->getType() == WT_Hydra)
		{
			SColor emissive = SColor(0xAAAAAAAA).getInterpolated(SColor(0x00000000), m_highlight[i]);
			setEmissiveColor(m_hydraPool, emissive);
		}
	}
}

